import pandas as pd
import numpy as np

def task_func(rows=100, columns=3):
    if not isinstance(rows, (int, np.integer)) or isinstance(rows, bool):
        raise TypeError("rows must be an integer")
    if not isinstance(columns, (int, np.integer)) or isinstance(columns, bool):
        raise TypeError("columns must be an integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")
    if columns > 26:
        raise ValueError("columns must be at most 26 when using single-letter column names")

    col_names = [chr(ord('a') + i) for i in range(columns)]
    alphabet = np.array(list("abcdefghijklmnopqrstuvwxyz"))

    data = np.random.choice(alphabet, size=(rows, columns))
    return pd.DataFrame(data, columns=col_names)
